SELECT (SELECT typeof(i)||':'||quote(i)||':'||typeof(s)||':'||hex(s) FROM s WHERE i=1) AS s1, (SELECT typeof(i)||':'||quote(i)||':'||typeof(s)||':'||hex(s) FROM s WHERE i=2) AS s2, (SELECT count(*) FROM s) AS s_count, (SELECT count(*) FROM e) AS e_count, (SELECT count(*) FROM e WHERE e='v1') AS v1_count, (SELECT count(*) FROM e WHERE e='v2') AS v2_count, (SELECT sql FROM sqlite_schema WHERE type='table' AND name='s') AS s_schema, (SELECT sql FROM sqlite_schema WHERE type='table' AND name='e') AS e_schema;